import{_ as s,C as r,o as t,c as i,a3 as o,b as l,w as a,a as d,E as h,a4 as c}from"./chunks/framework.DhF4LrUq.js";const w=JSON.parse('{"title":"Manage OTA bundles","description":"Manage OTA bundles - enable OTA for an app, copy the signing key for the SDK, issue the once-only sdc1. device token, upload and sign a bundle, revoke it, and author alert rules.","frontmatter":{"description":"Manage OTA bundles - enable OTA for an app, copy the signing key for the SDK, issue the once-only sdc1. device token, upload and sign a bundle, revoke it, and author alert rules."},"headers":[],"relativePath":"how-to/console/ota-bundles.md","filePath":"how-to/console/ota-bundles.md"}'),p={name:"how-to/console/ota-bundles.md"};function u(g,e,b,f,k,m){const n=r("Mermaid");return t(),i("div",null,[e[1]||(e[1]=o('<h1 id="manage-ota-bundles" tabindex="-1">Manage OTA bundles <a class="header-anchor" href="#manage-ota-bundles" aria-label="Permalink to &quot;Manage OTA bundles&quot;">​</a></h1><p>OTA bundles are authored per application, from the console&#39;s <strong>OTA bundles</strong> screen in the navigation. The model — what a bundle is, why only a signed one can publish — is <a href="/shipperdog/snapshot/concepts/ota-updates">OTA updates</a>; this page is the operator walk through every control on that screen and the application&#39;s OTA block, in the order a first bundle needs them.</p><h2 id="enable-ota-for-the-application" tabindex="-1">Enable OTA for the application <a class="header-anchor" href="#enable-ota-for-the-application" aria-label="Permalink to &quot;Enable OTA for the application&quot;">​</a></h2><ol><li>Open the application&#39;s detail page (<strong>Applications</strong>, then its row) and find the <strong>Over-the-air updates</strong> block.</li><li>Flip the toggle. A disabled application refuses bundle authoring, app-token issue, alert-rule creation, and the device check — the authoring surfaces answer <code>APPLICATION_NOT_OTA_ENABLED</code> until the toggle is on.</li></ol><p>The same block carries the <strong>Manage OTA bundles</strong> button, which jumps straight to the authoring screen.</p><h2 id="copy-the-signing-key-for-the-sdk" tabindex="-1">Copy the signing key for the SDK <a class="header-anchor" href="#copy-the-signing-key-for-the-sdk" aria-label="Permalink to &quot;Copy the signing key for the SDK&quot;">​</a></h2><p>Every bundle is Ed25519-signed by an app-scoped key. The key does not exist until the application&#39;s <strong>first finalized bundle</strong> generates it — a finalize-time act, never a read side effect — so the block shows <em>No signing key yet</em> until then.</p><p>Once it exists, the block shows the algorithm, the <code>keyId</code>, and the Base64 public key — with a <strong>Copy keyId</strong> button beside the <code>keyId</code> and a <strong>Copy</strong> button beside the public key:</p><ul><li><strong>Copy keyId</strong> and <strong>Copy</strong> (the public key) — the pair an app embeds so devices can verify signatures themselves. The private half never leaves ShipperDog&#39;s secret store.</li><li>Rotation is generational: a new <code>keyId</code> supersedes the old one, and signatures made under the old generation stay verifiable against its retained public half until the generation retires.</li></ul><h2 id="issue-the-device-app-token" tabindex="-1">Issue the device app token <a class="header-anchor" href="#issue-the-device-app-token" aria-label="Permalink to &quot;Issue the device app token&quot;">​</a></h2><p>The shipped app identifies itself with an <code>sdc1.</code> app token — an identifier, not a secret — issued once per application from the <strong>Device app tokens</strong> section of the OTA bundles screen:</p><ol><li>Click <strong>Issue token</strong>, give it a name (1-200 characters, how the registry distinguishes tokens), and confirm.</li><li>The <strong>Copy the app token now</strong> dialog shows the value <strong>exactly once</strong> — the registry stores only its SHA-256 and cannot recover it. Copy it, embed it in the app, and only then click <strong>I have stored it</strong>.</li></ol><p>To retire a compromised or retired-build token, click <strong>Revoke</strong> on its row: every device check presenting it fails from that moment on. Revoking an already-revoked token is a safe replay.</p><h2 id="upload-and-sign-a-bundle" tabindex="-1">Upload and sign a bundle <a class="header-anchor" href="#upload-and-sign-a-bundle" aria-label="Permalink to &quot;Upload and sign a bundle&quot;">​</a></h2><p>Click <strong>Upload bundle</strong> to open the wizard. Fill in:</p><ul><li><strong>Bundle version (semver triple)</strong> — labels the bundle&#39;s own versions row (for example <code>2.4.1</code>).</li><li><strong>Platform tag</strong> — an open vocabulary of 1-32 characters (for example <code>js-bundle</code>).</li><li><strong>Minimum app version (optional)</strong> — devices on older store builds never see the bundle.</li><li><strong>Forced</strong> — whether the update applies without asking.</li><li><strong>Choose the bundle archive</strong> — the platform-agnostic archive itself.</li></ul><p>One click — <strong>Create, upload, and sign</strong> — runs the whole chain:</p>',17)),(t(),l(c,null,{default:a(()=>[h(n,{id:"mermaid-102",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5BCreate%20the%20draft%20%2B%20upload%20session%5D%20--%3E%20B%5BUpload%20the%20archive%20direct%20to%20storage%5D%0A%20%20%20%20B%20--%3E%20C%5BFinalize%20-%20hash%20the%20stored%20bytes%20and%20sign%5D%0A%20%20%20%20C%20--%3E%20D%5BSIGNED%20bundle%20%2B%20its%20manifest%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>Finalize lands the <strong>SIGNED</strong> row and shows the manifest devices verify against: the <code>sha256</code>, size, platform tag, signing <code>keyId</code>, and the signature — with copy buttons on the checksum, the <code>keyId</code>, and the signature. If the secret store is momentarily unreachable the finalize answers <code>SIGNING_UNAVAILABLE</code> (503); retry it.</p><p>The screen&#39;s listing carries the SIGNED-and-later rows (Signed, Released, Revoked) with the status filter; draft and mid-upload rows are not listable.</p><h2 id="revoke-a-bundle" tabindex="-1">Revoke a bundle <a class="header-anchor" href="#revoke-a-bundle" aria-label="Permalink to &quot;Revoke a bundle&quot;">​</a></h2><p><strong>Revoke</strong> on a SIGNED bundle row withdraws it: the device check answers no-update for that bundle from then on. The confirmation dialog spells out the distinction — this is the <em>author&#39;s</em> withdrawal, not a device-side rollback.</p><p>A bundle that already belongs to a release cannot be revoked (<code>BUNDLE_NOT_REVOKABLE</code>): pull it back through the release&#39;s <a href="/shipperdog/snapshot/how-to/console/rollback">rollback</a> instead.</p><h2 id="author-alert-rules" tabindex="-1">Author alert rules <a class="header-anchor" href="#author-alert-rules" aria-label="Permalink to &quot;Author alert rules&quot;">​</a></h2><p>The <strong>OTA alert rules</strong> section watches the application&#39;s OTA metrics. Click <strong>New rule</strong> and set:</p><ul><li><strong>Metric</strong> — a count (checks, devices seen, downloads, applied, failures, rollbacks) or a fraction (apply failure rate, crash-free rate).</li><li><strong>Comparator and threshold</strong> — counts are integers; rates are 0..1 fractions (crash-free rate <code>&lt;</code> <code>0.995</code>, for example).</li><li><strong>Window</strong> — 1 to 10080 minutes.</li><li><strong>Severity</strong> — info, warning, or critical.</li><li><strong>Bundle scope (optional)</strong> — empty watches the whole application.</li></ul><p>Rules persist and fire into the <a href="/shipperdog/snapshot/how-to/console/ota-rollouts">OTA dashboard</a>&#39;s alerts feed and the notification channels; a rule with a standing firing wears a <strong>firing</strong> chip on its row. Deleting a rule that has ever fired is refused (<code>ALERT_RULE_HAS_FIRINGS</code>) — update it instead, so its firing history stays addressable.</p><h2 id="publish-and-roll-out" tabindex="-1">Publish and roll out <a class="header-anchor" href="#publish-and-roll-out" aria-label="Permalink to &quot;Publish and roll out&quot;">​</a></h2><p>A signed bundle publishes on an <a href="/shipperdog/snapshot/how-to/console/releases">ordinary release</a> over a ring whose distribution channel is <code>ota</code> — exactly one bundle per OTA release, the full governance stack included. From there the rollout is its own job: <a href="/shipperdog/snapshot/how-to/console/ota-rollouts">run OTA rollouts</a>.</p><p><strong>Related guides:</strong> <a href="/shipperdog/snapshot/how-to/console/ota-rollouts">run OTA rollouts</a> · <a href="/shipperdog/snapshot/how-to/console/releases">work with releases</a> · <a href="/shipperdog/snapshot/how-to/console/rollback">roll back a release</a> · <a href="/shipperdog/snapshot/concepts/ota-updates">OTA updates concepts</a></p>',12))])}const v=s(p,[["render",u]]);export{w as __pageData,v as default};
